@startuml
enum Suit {
  Diamonds
  Hearts
  Spades
  Clubs
}

enum ComparisonResult {
  Lower
  Equal
  Higher
}

enum SoloType {
  Trump
  Jack
  Queen
}

abstract class GameObject {
  + id : string
}

class Card {
  + suit : Suit
  + height : int
  + compareHeight(otherCard : Card) : ComparisonResult
}

class Deck {
  + totalCards : int
}

class ScoringTable {
  + totalScore : int
}

class Round {
  + pointValue : int
  + isJackRound : boolean
  + isSoloRound : boolean
}

class SoloRound {
  + soloType : SoloType
}

class MandatorySoloRound {
}

class Player {
  + name : string
}

class Game {
  + gameId : string
}

GameObject <|-- Card
GameObject <|-- Deck
GameObject <|-- ScoringTable
GameObject <|-- Round
GameObject <|-- Player
GameObject <|-- Game

Game "1" *-- "4" Player
Game "1" *-- "1" Deck
Game "1" *-- "1" ScoringTable
ScoringTable "1" *-- "1..*" Round
Round "1" *-- "0..*" Player
SoloRound --|> Round
MandatorySoloRound --|> SoloRound
Deck "1" *-- "0..48" Card

